package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import org.json.*;
/** Synthetic-only editor draft + picture viewer regression suite. */
public final class DraftPreviewTest extends DocumentEditorTest {
 JSONArray drafts()throws Exception{return (JSONArray)h.call("getDocumentDraft",new JSONObject());}
 String currentId()throws Exception{return new JSONArray("["+h.js("window.__lastId")+"]").getString(0);}
 boolean has(String id)throws Exception{JSONArray all=drafts();for(int i=0;i<all.length();i++)if(all.getJSONObject(i).getJSONObject("record").getString("id").equals(id))return true;return false;}
 void begin(String type)throws Exception{open(type);h.js("window.__lastId=null;window.__realNative=LifeNative;LifeNative={call:function(a,p,id){if(a==='saveDocumentDraft')__lastId=JSON.parse(p).draft.record.id;__realNative.call(a,p,id)}}");}
 void unhook()throws Exception{h.js("LifeNative=__realNative");}
 @Override public void onStart(){Bundle result=new Bundle();try{
  h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");int initial=drafts().length();
  for(String type:new String[]{"learning","work_note","idea","experience"}){open(type);click("#doc-info");click("#doc-meta-done");close();check(drafts().length()==initial,"Untouched "+type+" with opened metadata creates no draft");}
  open("learning");click("[data-doc-command=bold]");close();check(drafts().length()==initial,"Formatting an empty editor does not create a draft");
  open("learning");input("","短暂输入");input("","");close();check(drafts().length()==initial,"Typing then erasing before debounce leaves no blank draft");
  begin("idea");input("","会被删除的临时正文");Thread.sleep(950);String erased=currentId();check(has(erased),"Actual prose is autosaved before exit");input("","");close();check(!has(erased),"Erasing previously autosaved content removes only its empty draft");unhook();
  begin("experience");input("仅标题草稿","");close();String titleOnly=currentId();check(has(titleOnly),"Title-only draft survives exit");unhook();
  begin("learning");click("#doc-info");h.js("document.querySelector('[data-meta=durationMinutes]').value='25';document.querySelector('#doc-meta').dispatchEvent(new Event('input'))");click("#doc-meta-done");close();check(has(currentId()),"Intentional metadata-only duration remains recoverable");unhook();
  begin("idea");click("#doc-info");h.js("document.querySelector('[data-meta=occurredAt]').value='2026-10-18T12:00';document.querySelector('#doc-meta').dispatchEvent(new Event('input'))");click("#doc-meta-done");close();check(has(currentId()),"Intentional date/time-only change remains recoverable");unhook();
  JSONObject existing=new JSONObject().put("id","draft-precision-check").put("type","idea").put("date","2026-10-19").put("occurredAt","2026-10-19T09:15:47").put("title","已有记录不改时间秒数").put("note","原文不会被查看和预览修改。\n\n第二段。").put("tags",new JSONArray());h.call("saveRecord",new JSONObject().put("record",existing));h.js("window.__stored="+record("draft-precision-check")+";RecordEditor.open(__stored)");until("!!document.querySelector('#doc-body')");close();check(!has("draft-precision-check"),"Opening existing record preserves seconds and absent optional metadata without phantom draft");
  // Queue ordering: delay a real native draft save, erase while it is in flight.
  open("idea");h.js("window.__queueNative=LifeNative;window.__queuedId=null;LifeNative={call:function(a,p,id){if(a==='saveDocumentDraft'){__queuedId=JSON.parse(p).draft.record.id;setTimeout(()=>__queueNative.call(a,p,id),500)}else __queueNative.call(a,p,id)}}");input("","排队后清空");Thread.sleep(750);input("","");close();String q=new JSONArray("["+h.js("__queuedId")+"]").getString(0);check(!has(q),"In-flight autosave is followed by clear rather than resurrecting blank draft");h.js("LifeNative=__queueNative");
  // Historical blanks stay in native storage; the picker hides them, never deletes untitled prose.
  h.call("saveDocumentDraft",new JSONObject().put("draft",new JSONObject().put("record",new JSONObject().put("id","legacy-empty-card").put("type","idea").put("note","").put("title","").put("occurredAt","2026-10-19T12:30:00")).put("savedAt",System.currentTimeMillis()+10000)));
  JSONObject real=new JSONObject().put("id","legacy-untitled-card").put("type","experience").put("title","").put("note","# 未命名但真实的经验\n\n**hello world**：阅读后先写一段自己的理解，不要只抄原文。这里继续写正文以验证双行摘要的截断和卡片布局。再多写一些真实的思考和经验，长篇内容只在草稿卡片显示摘要，点击后仍然能够恢复全部内容，而不是截断原文。").put("date","2026-10-19").put("tags",new JSONArray());
  h.call("saveDocumentDraft",new JSONObject().put("draft",new JSONObject().put("record",real).put("savedAt",System.currentTimeMillis()+20000)));
  open("learning");click("#doc-drafts");until("!!document.querySelector('#doc-drafts-panel')");check(h.js("document.querySelector('[data-draft]').innerText.includes('未命名但真实的经验')").equals("true"),"Picker sorts recent draft first and derives readable untitled heading");check(has("legacy-empty-card"),"Legacy empty storage is not destructively migrated");
  check(h.js("!document.querySelector('[data-draft-id=legacy-empty-card]')").equals("true"),"Legacy default-only cards do not clutter picker");
  check(h.js("(()=>{const r=document.querySelector('#doc-drafts-panel').getBoundingClientRect();return r.top<2&&r.bottom<=innerHeight+1&&r.height>innerHeight*.9})()").equals("true"),"Draft overlay is actually visible and fills the phone viewport");
  check(h.js("(()=>{const cards=[...document.querySelectorAll('.doc-draft-card')];return cards.every(b=>{const r=b.getBoundingClientRect();return r.left>=0&&r.right<=innerWidth+1})&&getComputedStyle(document.querySelector('.doc-draft-excerpt')).webkitLineClamp==='2'})()").equals("true"),"Draft cards fit phone width with two-line snippets");h.screenshot("draft-cards.png");
  click("[data-draft]");check(h.js("DocumentRich.serialize(document.querySelector('#doc-body'))").contains("hello world"),"Untitled legacy draft restores its complete Markdown body");close();
  // Image-only drafts are preserved; preview in editing and reading never touches source.
  JSONObject img=(JSONObject)h.call("storeRecordImage",new JSONObject().put("data",image()).put("name","合成图片.png"));begin("learning");h.js("nativeEvent('recordImage',"+img+")");until("!!document.querySelector('#doc-body img')&&document.querySelector('#doc-body img').naturalWidth>0");h.js("window.__bodyBefore=DocumentRich.serialize(document.querySelector('#doc-body'))");
  h.tap("#doc-body img",false);until("!!document.querySelector('#doc-image-viewer img')&&document.querySelector('#doc-image-viewer img').naturalWidth>0");check(h.js("document.querySelector('#doc-image-scale').textContent").equals(JSONObject.quote("100%")),"Native screen tap opens image in fit-to-screen viewer");click("#doc-image-plus");check(h.js("document.querySelector('#doc-image-scale').textContent").equals(JSONObject.quote("150%")),"Viewer zoom button enlarges image");
  h.js("(()=>{const v=document.querySelector('.doc-image-canvas'),a=new Event('touchstart');a.touches=[{clientX:80,clientY:200},{clientX:180,clientY:200}];v.dispatchEvent(a);const b=new Event('touchmove',{cancelable:true});b.touches=[{clientX:40,clientY:200},{clientX:240,clientY:200}];v.dispatchEvent(b)})()");check(h.js("document.querySelector('#doc-image-scale').textContent").equals(JSONObject.quote("300%")),"Two-finger gesture scales image");h.screenshot("image-preview.png");
  check(h.js("(()=>{const c=document.querySelector('.doc-image-canvas');c.scrollLeft=40;return c.scrollWidth>c.clientWidth&&c.scrollLeft>0})()").equals("true"),"Enlarged image supports horizontal panning without moving the toolbar");
  click("#doc-image-reset");check(h.js("document.querySelector('#doc-image-scale').textContent").equals(JSONObject.quote("100%")),"Fit-to-screen resets zoom");h.js("document.querySelector('.doc-image-canvas').dispatchEvent(new MouseEvent('dblclick',{clientX:150,clientY:300,cancelable:true}))");check(h.js("document.querySelector('#doc-image-scale').textContent").equals(JSONObject.quote("250%")),"Double click enlarges picture");h.js("RecordEditor.back()");check(h.js("!document.querySelector('#doc-image-viewer')&&DocumentRich.serialize(document.querySelector('#doc-body'))===__bodyBefore").equals("true"),"Back closes only viewer and leaves image token/source unchanged");
  click("#doc-mode");click("#doc-flow img");until("!!document.querySelector('#doc-image-viewer')");check(true,"Reader images also open enlarged preview");click("#doc-image-close");click("#doc-mode");close();check(has(currentId()),"Image-only draft survives both reader preview and editor exit");unhook();
  check(has(titleOnly),"Other meaningful drafts are not cleared by unrelated empty edits");
  result.putString("stream","PASS DraftPreviewTest: "+passed+" checks\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable err){try{h.screenshot("draft-preview-failure.png");}catch(Exception ignored){}result.putString("stream","FAIL DraftPreviewTest after "+passed+": "+err+"\n");finish(Activity.RESULT_CANCELED,result);}}
}
